def generar_contenido_estatico(kw: str, categoria: str, lang: str = "es") -> str:
    """
    Genera contenido estático ÚNICO por página combinando:
    - 1 párrafo de apertura (elegido entre 4 variantes por idioma)
    - 1 párrafo núcleo (contenido de categoría existente, cuando lo hay,
      o CORE_GENERIC nativo para los idiomas que antes caían en inglés)
      + 1 frase de cierre CTA (elegida entre 4 variantes por idioma)
    Selección determinística por hash(kw+categoria+lang): mismo resultado
    en cada rebuild (estable para Google), pero distinto entre páginas.
    Sin llamadas a API — costo $0.
    """
    tpl_key = CATEGORY_MAP.get(categoria, "general")

    # ── Párrafo núcleo ──
    core = None
    lang_tpl = LANG_TEMPLATES.get(lang)
    if lang_tpl:
        key = tpl_key if tpl_key in lang_tpl else ("general" if "general" in lang_tpl else None)
        if key:
            core = random.choice(lang_tpl[key])[0]
    if core is None:
        core = CORE_GENERIC.get(lang)
    if core is None:
        core = LANG_TEMPLATES["en"]["general"][0][0]

    # ── Selección determinística de intro/cierre ──
    h = int(hashlib.md5(f"{kw}|{categoria}|{lang}".encode("utf-8")).hexdigest(), 16)
    intros = INTRO_BANK.get(lang, INTRO_BANK["en"])
    cierres = CIERRE_BANK.get(lang, CIERRE_BANK["en"])
    intro = intros[h % len(intros)]
    cierre = cierres[(h // len(intros)) % len(cierres)]

    p1 = intro.replace("{kw}", kw)
    p2 = f"{core} {cierre}".replace("{kw}", kw)

    return f"<p>{p1}</p><p>{p2}</p>"
